// Core tests. Every expected value comes from the vendored SPEC fixtures
// (test/fixtures.json, spec candidate 548ffc2efc37072e11080e229d24c281683e7c79)
// or is derived by hand from the SPEC pipeline; nothing is generated by
// the implementation under test.

import assert from "node:assert/strict";
import { readFile } from "node:fs/promises";
import test from "node:test";

import { formatDuration, run } from "../public/js/core/ev-charging.mjs";

const fixtures = JSON.parse(
  await readFile(new URL("./fixtures.json", import.meta.url), "utf8"),
);

const coreCases = fixtures.cases.filter((entry) => entry.kind === "core");
assert.equal(coreCases.length, 8);

for (const entry of coreCases) {
  test(`fixture ${entry.id}`, () => {
    assert.deepEqual(run(entry.input), entry.expected);
  });
}

const BASE = {
  capacityKwh: "60",
  currentSoc: "20",
  targetSoc: "80",
  chargerPowerKw: "7",
  efficiencyPct: "90",
  pricePerKwh: "",
};

function expectError(input, code, field) {
  assert.deepEqual(run(input), { ok: false, error: { code, field, row: null } });
}

test("schema: non-object, missing field, extra field, wrong type, accessor", () => {
  expectError(null, "SCHEMA", null);
  expectError("60", "SCHEMA", null);
  expectError([1, 2], "SCHEMA", null);
  const missing = { ...BASE };
  delete missing.pricePerKwh;
  expectError(missing, "SCHEMA", null);
  expectError({ ...BASE, extra: "1" }, "SCHEMA", null);
  expectError({ ...BASE, capacityKwh: 60 }, "SCHEMA", null);
  const accessor = { ...BASE };
  Object.defineProperty(accessor, "capacityKwh", {
    enumerable: true,
    get() {
      return "60";
    },
  });
  expectError(accessor, "SCHEMA", null);
});

test("field order: the first failing field in the fixed order wins", () => {
  // capacity (format) fails before efficiency (range).
  expectError({ ...BASE, capacityKwh: "1.234", efficiencyPct: "101" }, "DECIMAL_FORMAT", "capacityKwh");
  // currentSoc (empty) fails before targetSoc (format).
  expectError({ ...BASE, currentSoc: "", targetSoc: "x" }, "EMPTY", "currentSoc");
  // Field validation completes before the cross-field SOC_ORDER check.
  expectError({ ...BASE, currentSoc: "80", targetSoc: "50", efficiencyPct: "101" }, "RANGE", "efficiencyPct");
});

test("per-field checks: limit, unicode, empty, formats, ranges", () => {
  expectError({ ...BASE, capacityKwh: "1234567890123" }, "INPUT_LIMIT", "capacityKwh");
  expectError({ ...BASE, currentSoc: "\uD800" }, "UNICODE", "currentSoc");
  expectError({ ...BASE, targetSoc: "" }, "EMPTY", "targetSoc");
  expectError({ ...BASE, chargerPowerKw: "7.555" }, "DECIMAL_FORMAT", "chargerPowerKw");
  expectError({ ...BASE, currentSoc: "20.5" }, "INTEGER_FORMAT", "currentSoc");
  expectError({ ...BASE, efficiencyPct: "90.0" }, "INTEGER_FORMAT", "efficiencyPct");
  expectError({ ...BASE, capacityKwh: "0" }, "RANGE", "capacityKwh");
  expectError({ ...BASE, capacityKwh: "500.01" }, "RANGE", "capacityKwh");
  expectError({ ...BASE, capacityKwh: "060" }, "DECIMAL_FORMAT", "capacityKwh");
  expectError({ ...BASE, currentSoc: "007" }, "INTEGER_FORMAT", "currentSoc");
  expectError({ ...BASE, currentSoc: "101" }, "RANGE", "currentSoc");
  expectError({ ...BASE, chargerPowerKw: "0" }, "RANGE", "chargerPowerKw");
  expectError({ ...BASE, chargerPowerKw: "1000.01" }, "RANGE", "chargerPowerKw");
  expectError({ ...BASE, efficiencyPct: "49" }, "RANGE", "efficiencyPct");
  expectError({ ...BASE, pricePerKwh: "100.01" }, "RANGE", "pricePerKwh");
  expectError({ ...BASE, pricePerKwh: "-1" }, "DECIMAL_FORMAT", "pricePerKwh");
  expectError({ ...BASE, pricePerKwh: " " }, "DECIMAL_FORMAT", "pricePerKwh");
});

test("legal endpoints succeed", () => {
  const maxed = run({
    capacityKwh: "500",
    currentSoc: "0",
    targetSoc: "100",
    chargerPowerKw: "1000",
    efficiencyPct: "50",
    pricePerKwh: "100",
  });
  // battery = 500, wall = 500 * 100 / 50 = 1000, time = 1000/1000*60 = 60,
  // cost = 1000 * 100 = 100000.
  assert.deepEqual(maxed, {
    ok: true,
    result: {
      needsCharge: true,
      energyBatteryKwh: "500.00",
      energyWallKwh: "1000.00",
      timeMinutes: 60,
      cost: 100000,
    },
  });
  const pricey = run({ ...BASE, pricePerKwh: "0" });
  assert.equal(pricey.ok, true);
  assert.equal(pricey.result.cost, 0);
});

test("delta of 1 percent and exact half-up from the exact value", () => {
  // 10 kWh pack, 1% => battery 0.10; wall = 0.10 * 100 / 80 = 0.125 -> 0.13;
  // time = 0.125 / 10 * 60 = 0.75 -> 1; no price -> cost null.
  const outcome = run({
    capacityKwh: "10",
    currentSoc: "50",
    targetSoc: "51",
    chargerPowerKw: "10",
    efficiencyPct: "80",
    pricePerKwh: "",
  });
  assert.deepEqual(outcome, {
    ok: true,
    result: {
      needsCharge: true,
      energyBatteryKwh: "0.10",
      energyWallKwh: "0.13",
      timeMinutes: 1,
      cost: null,
    },
  });
});

test("wall energy is never below battery energy on success", () => {
  for (const entry of coreCases) {
    if (!entry.expected.ok) continue;
    const outcome = run(entry.input);
    assert.ok(
      Number(outcome.result.energyWallKwh) >= Number(outcome.result.energyBatteryKwh),
      entry.id,
    );
  }
});

test("hostile strings stay inert data and fail by the fixed rules", () => {
  expectError({ ...BASE, capacityKwh: "<script>" }, "DECIMAL_FORMAT", "capacityKwh");
  expectError({ ...BASE, capacityKwh: "1e3" }, "DECIMAL_FORMAT", "capacityKwh");
  expectError({ ...BASE, currentSoc: "２０" }, "INTEGER_FORMAT", "currentSoc");
});

test("formatDuration follows the pinned display rules", () => {
  assert.equal(formatDuration(0, "zh-Hant"), "0 分");
  assert.equal(formatDuration(0, "en"), "0 min");
  assert.equal(formatDuration(59, "zh-Hant"), "59 分");
  assert.equal(formatDuration(59, "en"), "59 min");
  assert.equal(formatDuration(60, "zh-Hant"), "1 小時 00 分");
  assert.equal(formatDuration(60, "en"), "1 h 00 min");
  assert.equal(formatDuration(343, "zh-Hant"), "5 小時 43 分");
  assert.equal(formatDuration(343, "en"), "5 h 43 min");
  assert.equal(formatDuration(1500, "zh-Hant"), "25 小時 00 分");
});
